import * as React from "react";
import { useState, useEffect } from "react";
import TopNav from "../topNav/TopNav";
import "./TopNavigation.scss";
import Button from "../button/Button";
import IconButton from "../iconButton/IconButton";
import SearchBar from "../topNav/SearchBar";
import TopNavBlock from "../topNavBlock/TopNavBlock";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon, SvgMpaLogo } from "../../assets/icons";
import { MpaLogo } from "../logo/MpaLogo";
import { Avatar } from "../avatar";
export interface TopNavigationHeaderProps {

    /**
    * Unique identifier for the topnavigation
    */
    id: string;

    /** Array of navigation items */
    navItems: {
        label: string;
        header?: string;
        desc?: string;
        link?: string;
        menuItems: {
            label: string;
            leadingIcon?: keyof typeof SvgMpaIcon | string;
            showDivider?: boolean;
            disabled?: boolean;
            subMenuItems?: any;
        }[];
    }[];

    /** Logo icon name or path */
    logo?: keyof typeof SvgMpaLogo | string;


    // logo : JSX.Element,    
    /** Layout type */
    layout?: "menu-block" | "mega-menu";

    /** Toggle for showing the search bar */
    showSearch?: boolean;

    /** Toggle for showing login button */
    showLogin?: boolean;

    /** Toggle for showing avatar */
    showAvatar?: boolean;

    /** Optional header text */
    headerText?: string;

    /** Optional class name for the top navigation */
    className?: string;

    /** Optional colour theme for buttons/icons */
    colour: "primary" | "secondary" | "tertiary";


    /**
     * Optional click handler.
     * You can use it to trigger a modal, redirect, or any custom logic.
     */
    loginOnClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;

    logoUrl?: string;

    headerNavItems?: {
        label: string;
        link?: string;
        iconName?: keyof typeof SvgMpaIcon | string;

    }[];

    /* Pass your own Router Link from application */
    LinkComponent?: React.ComponentType<any>;

    /* Optional indicator for if the nav bar is 1-level deep */
    isSingleLevel?: boolean;

}


const TopNavigationHeader: React.FC<TopNavigationHeaderProps> = ({ id, navItems, layout = "menu-block", showSearch = "true", logo = "DigitalportLogo", showLogin = false, showAvatar = true, headerText = "SXXX6226A", colour = "primary", className = "navHeader", loginOnClick, logoUrl, headerNavItems, LinkComponent, isSingleLevel = false }) => {

    const [openIndex, setOpenIndex] = React.useState<number | null>(null);
    const [isSearchVisible, setSearchVisible] = useState(false);

    const [windowWidth, setWindowWidth] = useState(window.innerWidth);

    const showSearchBar = () => {
        setSearchVisible(!isSearchVisible);

        if (!isSearchVisible) {
            setOpenIndex(null); // Close the menu when the search bar is shown
        }
    };

    const searchBoxClass = `${isSearchVisible ? 'show' : 'hide'}`;
    const isMobile = windowWidth < 768;

    useEffect(() => {
        const handleResize = () => {
            setWindowWidth(window.innerWidth);
        };
        // Add event listener for resizing
        window.addEventListener('resize', handleResize);

        // Cleanup the event listener when the component is unmounted
        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    const [isUserMenuOpen, setUserMenuOpen] = useState(false);

    const toggleUserMenu = (e: React.MouseEvent) => {
        if (!isSingleLevel) {
            e.stopPropagation();
            setUserMenuOpen(prev => !prev);
        }
    };

    const toggleSingleLevelMenu = () => {
        setSearchVisible(prev => !prev);
    }

    return (
        <>
            {/* Conditional rendering based on mobile width */}
            {isMobile ? (
                <>
                    <div className="top-nav-mobile">
                        <div className="main-top-nav">
                            {logoUrl ? (<a href={logoUrl}><div className="logo-container">
                                {logo && (<MpaLogo logoName={logo} width={60} height={60} />)}
                            </div>
                            </a>) : (<div className="logo-container">
                                {logo && (<MpaLogo logoName={logo} width={60} height={60} />)}
                            </div>)}
                            <div className="header-action navHeader-action">


                                <div className="auth-container mobile-auth">
                                    <Avatar
                                        id={"avatarId"}
                                        size="small"
                                        type="icon"
                                        icon="User_Filled"
                                        showMenuBlock={false}
                                    />

                                    <span
                                        className="chevron-toggle"
                                        onClick={toggleUserMenu}
                                        role="button"
                                        aria-expanded={isUserMenuOpen}
                                    >
                                        <MpaIcon iconName={isUserMenuOpen ? "ChevronUp" : "ChevronDown"} />
                                    </span>

                                    {isUserMenuOpen && headerNavItems?.length && (
                                        <div className="user-dropdown-menu mobile-dropdown">
                                            <ul className="header-dropdown-list">
                                                {headerNavItems.map((item, index) => (
                                                    <li key={index} className="header-dropdown-item">
                                                        {item.link ? (
                                                            <a
                                                                href={item.link}
                                                                onClick={() => setUserMenuOpen(false)}
                                                            >
                                                                {item.iconName && (
                                                                    <MpaIcon iconName={item.iconName} size={18} />
                                                                )}
                                                                {item.label}
                                                            </a>
                                                        ) : (
                                                            <span>
                                                                {item.iconName && (
                                                                    <MpaIcon iconName={item.iconName} size={18} />
                                                                )}
                                                                {item.label}
                                                            </span>
                                                        )}
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    )}
                                </div>


                                <div className={`search-container`}>
                                    <IconButton
                                        id={"iconButtonId"}
                                        className={`icon-btn icon-btn-square icon-btn-${colour}`}
                                        icon={isSearchVisible ? 'X' : 'Menu2'}
                                        btnType={"standard"}
                                        onClick={showSearchBar}
                                    />
                                </div>
                            </div>
                        </div>


                    </div>
                    {showSearch && <SearchBar className={`search-box ${searchBoxClass}`} buttonClassName={`icon-btn icon-btn-square icon-btn-${colour}`} />}
                    {isSearchVisible && (
                        <TopNavBlock id="topNavBlockId" navItems={navItems} colour={colour} LinkComponent={LinkComponent} isSingleLevel={isSingleLevel} toggleMenu={toggleSingleLevelMenu} />
                    )}
                </>

            ) : (
                <div>
                    <TopNav id="topNavId" navItems={navItems} layout={layout} showSearch={showSearch} showLogin={showLogin} showAvatar={showAvatar} colour={colour} logo={logo} headerText={headerText} className={className} logoUrl={logoUrl} headerNavItems={headerNavItems} LinkComponent={LinkComponent} isSingleLevel={isSingleLevel} />
                </div>
            )}
        </>
    );

};

export default TopNavigationHeader;
